-- +goose Up

-- IDs become UUIDs so nobody can walk the catalogue by counting. They are
-- generated by the services (uuid.New()), so the columns have no default.
--
-- The conversion does not carry rows across, so it refuses to run on
-- tables that have any. Both were empty when this was written.
-- +goose StatementBegin
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM products) OR EXISTS (SELECT 1 FROM product_images) THEN
    RAISE EXCEPTION 'products or product_images has rows; this migration only converts empty tables';
  END IF;
END $$;
-- +goose StatementEnd

ALTER TABLE product_images DROP CONSTRAINT product_images_product_id_fkey;

ALTER TABLE products
  ALTER COLUMN id DROP DEFAULT,
  ALTER COLUMN id TYPE UUID USING gen_random_uuid();
DROP SEQUENCE products_id_seq;

ALTER TABLE product_images
  ALTER COLUMN id DROP DEFAULT,
  ALTER COLUMN id TYPE UUID USING gen_random_uuid(),
  ALTER COLUMN product_id TYPE UUID USING gen_random_uuid();
DROP SEQUENCE product_images_id_seq;

ALTER TABLE product_images
  ADD CONSTRAINT product_images_product_id_fkey
  FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE;

-- +goose Down

-- +goose StatementBegin
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM products) OR EXISTS (SELECT 1 FROM product_images) THEN
    RAISE EXCEPTION 'products or product_images has rows; this migration only converts empty tables';
  END IF;
END $$;
-- +goose StatementEnd

ALTER TABLE product_images DROP CONSTRAINT product_images_product_id_fkey;

CREATE SEQUENCE products_id_seq;
ALTER TABLE products
  ALTER COLUMN id TYPE BIGINT USING nextval('products_id_seq'),
  ALTER COLUMN id SET DEFAULT nextval('products_id_seq');
ALTER SEQUENCE products_id_seq OWNED BY products.id;

CREATE SEQUENCE product_images_id_seq;
ALTER TABLE product_images
  ALTER COLUMN id TYPE BIGINT USING nextval('product_images_id_seq'),
  ALTER COLUMN id SET DEFAULT nextval('product_images_id_seq'),
  ALTER COLUMN product_id TYPE BIGINT USING 0;
ALTER SEQUENCE product_images_id_seq OWNED BY product_images.id;

ALTER TABLE product_images
  ADD CONSTRAINT product_images_product_id_fkey
  FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE;
